'use strict';

// Retry helper behind the outbound webhook sender.
//
// retry(fn, options) calls fn(attempt) and calls it again when the failure
// looks transient. Options:
//   attempts  total number of calls to fn, counting the first one
//   baseMs    starting delay between calls
//   wait      injected by tests so they do not spend real time waiting

const DEFAULT_ATTEMPTS = 3;
const DEFAULT_BASE_MS = 100;
const MAX_DELAY_MS = 2000;

// Node socket level failures that say nothing about the request itself.
const TRANSPORT_CODES = ['ECONNRESET', 'ETIMEDOUT', 'EAI_AGAIN'];

function defaultWait(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}

// Failures we are willing to send again.
function isRetryable(err) {
  if (!err) return false;
  if (TRANSPORT_CODES.indexOf(err.code) !== -1) return true;
  if (typeof err.status === 'number') return err.status >= 400;
  return false;
}

// Exponential backoff with a ceiling, so one dead endpoint cannot stall the
// whole delivery queue.
function backoffDelay(attempt, baseMs) {
  const base = typeof baseMs === 'number' ? baseMs : DEFAULT_BASE_MS;
  return Math.min(base * Math.pow(2, attempt), MAX_DELAY_MS);
}

async function retry(fn, options) {
  const opts = options || {};
  const attempts = typeof opts.attempts === 'number' ? opts.attempts : DEFAULT_ATTEMPTS;
  const baseMs = typeof opts.baseMs === 'number' ? opts.baseMs : DEFAULT_BASE_MS;
  const wait = typeof opts.wait === 'function' ? opts.wait : defaultWait;

  let lastErr;
  for (let attempt = 0; attempt <= attempts; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastErr = err;
      if (!isRetryable(err)) throw err;
      await wait(backoffDelay(attempts, baseMs));
    }
  }
  throw lastErr;
}

module.exports = {
  retry,
  isRetryable,
  backoffDelay,
  DEFAULT_ATTEMPTS,
  DEFAULT_BASE_MS,
  MAX_DELAY_MS,
};

