'use strict';

const { retry } = require('./retry.js');

// Delivers one webhook body through the injected transport. The transport
// rejects with an error carrying either a numeric HTTP status or a node
// error code, which is what the retry helper classifies on.
async function sendWebhook(transport, url, payload) {
  return retry(
    function (attempt) {
      return transport(url, { body: JSON.stringify(payload), attempt: attempt });
    },
    { attempts: 3, baseMs: 250 }
  );
}

module.exports = { sendWebhook };

