const queued = [];

function check(name, fn) {
  queued.push({ name: name, fn: fn });
}

function httpError(status, extra) {
  return Object.assign(new Error('http ' + status), { status: status }, extra || {});
}

function codeError(code) {
  return Object.assign(new Error(code), { code: code });
}

// Runs fn until it settles, recording every call and every wait.
async function record(thrower, options) {
  const calls = [];
  const delays = [];
  const opts = Object.assign({ baseMs: 100 }, options || {});
  opts.wait = async function (ms) {
    delays.push(ms);
  };
  let thrown = null;
  let value;
  try {
    value = await retry(function (attempt) {
      calls.push(attempt);
      return thrower(attempt);
    }, opts);
  } catch (err) {
    thrown = err;
  }
  return { calls: calls, delays: delays, thrown: thrown, value: value };
}

