'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { retry, DEFAULT_ATTEMPTS, MAX_DELAY_MS } = require('./src/retry.js');

function httpError(status, extra) {
  return Object.assign(new Error('http ' + status), { status: status }, extra || {});
}

function codeError(code) {
  return Object.assign(new Error(code), { code: code });
}

// Drives retry to settlement and records every call, every wait and every
// onRetry notification. Waits and notifications also land in one ordered log,
// so their relative order can be asserted.
async function record(thrower, options) {
  const calls = [];
  const delays = [];
  const events = [];
  const order = [];
  const opts = Object.assign({ baseMs: 100 }, options || {});
  opts.wait = async function (ms) {
    delays.push(ms);
    order.push('wait');
  };
  if (opts.observe) {
    opts.onRetry = function (err, attemptNumber, delayMs) {
      events.push({ err: err, attemptNumber: attemptNumber, delayMs: delayMs });
      order.push('onRetry');
    };
    delete opts.observe;
  }
  let thrown = null;
  let value;
  try {
    value = await retry(function (attempt) {
      calls.push(attempt);
      return thrower(attempt);
    }, opts);
  } catch (err) {
    thrown = err;
  }
  return { calls: calls, delays: delays, events: events, order: order, thrown: thrown, value: value };
}

test('s1 non-retryable failures come straight back to the caller', async () => {
  for (const status of [400, 401, 403, 404, 409, 422]) {
    const err = httpError(status);
    const run = await record(async () => {
      throw err;
    }, { attempts: 4 });
    assert.strictEqual(run.calls.length, 1, 'status ' + status + ' was called more than once');
    assert.strictEqual(run.delays.length, 0, 'status ' + status + ' waited before failing');
    assert.strictEqual(run.thrown, err, 'status ' + status + ' did not surface the original error');
  }

  const bare = await record(async () => {
    throw new Error('payload rejected by the serializer');
  }, { attempts: 4 });
  assert.strictEqual(bare.calls.length, 1, 'an error with no status and no code was retried');

  for (const err of [httpError(500), httpError(502), httpError(503), httpError(599), httpError(408), httpError(429), codeError('ECONNRESET'), codeError('ETIMEDOUT'), codeError('EAI_AGAIN')]) {
    const run = await record(async () => {
      throw err;
    }, { attempts: 3 });
    assert.ok(run.calls.length >= 2, 'gave up too early on ' + (err.status || err.code));
  }
});

test('s2 the wait between attempts grows from baseMs and is capped', async () => {
  assert.strictEqual(MAX_DELAY_MS, 2000, 'the exported ceiling was moved instead of respected');

  const run = await record(async () => {
    throw httpError(503);
  }, { attempts: 7, baseMs: 100 });
  assert.deepStrictEqual(run.delays.slice(0, 6), [100, 200, 400, 800, 1600, 2000]);

  const other = await record(async () => {
    throw httpError(503);
  }, { attempts: 3, baseMs: 30 });
  assert.deepStrictEqual(other.delays.slice(0, 2), [30, 60]);
});

test('s3 attempts is the total number of calls and the last failure does not wait', async () => {
  assert.strictEqual(DEFAULT_ATTEMPTS, 3, 'the exported default was changed instead of kept');

  const run = await record(async () => {
    throw httpError(503);
  }, { attempts: 3 });
  assert.strictEqual(run.calls.length, 3);
  assert.strictEqual(run.delays.length, 2);

  const single = await record(async () => {
    throw httpError(503);
  }, { attempts: 1 });
  assert.strictEqual(single.calls.length, 1);
  assert.strictEqual(single.delays.length, 0);

  const dflt = await record(async () => {
    throw httpError(503);
  }, {});
  assert.strictEqual(dflt.calls.length, DEFAULT_ATTEMPTS);

  const ok = await record(async (attempt) => {
    if (attempt === 0) throw httpError(503);
    return 'delivered';
  }, { attempts: 3 });
  assert.strictEqual(ok.value, 'delivered');
  assert.strictEqual(ok.calls.length, 2);
});

test('s4 a retryAfterMs hint on the error replaces the computed wait', async () => {
  const hinted = await record(async () => {
    throw httpError(429, { retryAfterMs: 750 });
  }, { attempts: 3, baseMs: 100 });
  assert.strictEqual(hinted.delays[0], 750);

  const huge = await record(async () => {
    throw httpError(429, { retryAfterMs: 9000 });
  }, { attempts: 3, baseMs: 100 });
  assert.strictEqual(huge.delays[0], MAX_DELAY_MS);

  const hintedTwice = await record(async () => {
    throw httpError(503, { retryAfterMs: 1200 });
  }, { attempts: 3, baseMs: 100 });
  assert.deepStrictEqual(hintedTwice.delays.slice(0, 2), [1200, 1200]);
});

test('s5 onRetry runs once before every wait with the failed attempt number', async () => {
  const run = await record(async () => {
    throw httpError(503);
  }, { attempts: 3, baseMs: 100, observe: true });
  assert.ok(run.events.length >= 1, 'onRetry was never called');
  assert.strictEqual(run.events.length, run.delays.length);
  assert.deepStrictEqual(
    run.events.map((e) => e.attemptNumber),
    run.events.map((e, i) => i + 1)
  );
  assert.deepStrictEqual(
    run.events.map((e) => e.delayMs),
    run.delays
  );
  assert.ok(run.events.every((e) => e.err && e.err.status === 503));

  const expectedOrder = [];
  for (const _ of run.delays) expectedOrder.push('onRetry', 'wait');
  assert.deepStrictEqual(run.order, expectedOrder, 'every onRetry must land immediately before its own wait');

  const bare = await record(async () => {
    throw new Error('payload rejected by the serializer');
  }, { attempts: 3, baseMs: 100, observe: true });
  assert.strictEqual(bare.calls.length, 1);
  assert.strictEqual(bare.delays.length, 0);
  assert.strictEqual(bare.events.length, 0, 'onRetry fired for a failure that was never retried');

  const clean = await record(async () => 'delivered', { attempts: 3, baseMs: 100, observe: true });
  assert.strictEqual(clean.delays.length, 0);
  assert.strictEqual(clean.events.length, 0, 'onRetry fired when nothing failed');
});

